package com.crypto.laplace.scheduler;
import static org.mockito.Mockito.*;import com.crypto.domain.model.Kline;import com.crypto.laplace.execution.LaplacePaperExecutionService;import com.crypto.laplace.model.LaplacePositionStatus;import com.crypto.laplace.persistence.*;import com.crypto.laplace.service.*;import java.time.Instant;import java.util.List;import org.junit.jupiter.api.Test;
class LaplaceStopLossFanOutSchedulerTest{
 @Test void loadsOneCandleAndFansOutSameInstance(){var gate=mock(LaplaceMarketDataGate.class);var tr=mock(LaplaceRuntimeService.class);var fr=mock(LaplaceInvertedFalseRuntimeService.class);var tp=mock(LaplacePaperPositionRepository.class);var fp=mock(LaplaceInvertedFalsePositionRepository.class);var klines=mock(FiveMinuteKlineService.class);var te=mock(LaplaceStopLossScheduler.class);var fe=mock(LaplaceInvertedFalseStopLossScheduler.class);when(gate.enabledTrue()).thenReturn(true);when(gate.enabledFalse()).thenReturn(true);when(tr.isActive()).thenReturn(true);when(fr.isActive()).thenReturn(true);var a=LaplacePaperPositionEntity.builder().id("t").symbol("BTCUSDT").build();var b=LaplaceInvertedFalsePositionEntity.builder().id("f").symbol("BTCUSDT").build();when(tp.findByStrategyAndStatus(any(),eq(LaplacePositionStatus.OPEN))).thenReturn(List.of(a));when(fp.findByStrategyAndStatus(any(),eq(LaplacePositionStatus.OPEN))).thenReturn(List.of(b));var candle=Kline.builder().closeTime(Instant.parse("2026-08-14T00:04:59Z")).build();when(klines.loadLatestClosed("BTCUSDT")).thenReturn(candle);new LaplaceStopLossFanOutScheduler(gate,tr,fr,tp,fp,klines,te,fe).evaluate();verify(klines,times(1)).loadLatestClosed("BTCUSDT");verify(te).evaluate("t","BTCUSDT",same(candle));verify(fe).evaluate("f","BTCUSDT",same(candle));}
}
